import unittest
from router import Router


def make():
    r = Router()
    r.add("/users/<id>", "user")
    r.add("/", "home")
    return r


class Regression(unittest.TestCase):
    def test_root_still_matches(self):
        self.assertEqual(make().match("/"), ("home", {}))

    def test_unknown_paths_return_none(self):
        self.assertIsNone(make().match("/nope"))

    def test_parameters_are_captured(self):
        self.assertEqual(make().match("/users/42"), ("user", {"id": "42"}))

